export function computeStatus(entry) {
  if (entry.attn && !entry.attnResolved) return 'flagged';
  // Self pay: done if no unresolved ATTN
  const isSelf = (/self|oop|out.of.pocket/i.test(entry.payor1||'') || entry._payorNoInsurance) && !entry.payor2;
  if (isSelf) return 'done';
  if (entry.attnResolved) return 'done';
  // No payor at all — done
  if (!entry.payor1) return 'done';
  // Insurance: done only when ALL selected payors have been paid
  const p1done = !entry.payor1 || entry.payor1 === 'Self' || !!entry.insurancePaid1;
  const p2done = !entry.payor2 || !!entry.insurancePaid2;
  const p3done = !entry.payor3 || !!entry.insurancePaid3;
  if (p1done && p2done && p3done && (entry.insurancePaid1 || entry.insurancePaid2 || entry.insurancePaid3)) return 'done';
  // Partial — at least one paid but not all
  if (entry.insurancePaid1 || entry.insurancePaid2 || entry.insurancePaid3) return 'partial';
  return 'pending';
}

export function uid() { return Math.random().toString(36).slice(2, 9); }
export function today() { return new Date().toISOString().slice(0, 10); }
export function fmtDate(d) {
  if (!d) return '—';
  return new Date(d + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}
export function fmt$(n) {
  if (!n && n !== 0) return '—';
  const num = parseFloat(n);
  if (isNaN(num)) return '—';
  if (num === 0) return '$0';
  const formatted = num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return '$' + (formatted.endsWith('.00') ? formatted.slice(0, -3) : formatted);
}
// Fiscal week anchor: Week 1 of 2026 starts Sunday Jan 4, 2026
const FISCAL_ANCHOR_SUNDAY = new Date('2026-01-04T00:00:00');

export function getFiscalWeekInfo(dateStr) {
  if (!dateStr) return { week: 1, year: 2026, weekStart: '2026-01-04', weekEnd: '2026-01-10' };
  const d = new Date(dateStr + 'T00:00:00');
  // Find the Sunday on or before this date
  const dayOfWeek = d.getDay(); // 0=Sun, 6=Sat
  const thisSunday = new Date(d);
  thisSunday.setDate(d.getDate() - dayOfWeek);
  // Days from anchor Sunday
  const diffDays = Math.round((thisSunday - FISCAL_ANCHOR_SUNDAY) / 86400000);
  const diffWeeks = Math.floor(diffDays / 7);
  // Week 1 of 2026 = diffWeeks 0
  // Count backward: 2025 had 53 weeks, so week 53 of 2025 starts at diffWeeks=-1
  let fiscalWeek, fiscalYear;
  if (diffWeeks >= 0) {
    // 2026 forward: weeks 1-52 per year
    fiscalYear = 2026 + Math.floor(diffWeeks / 52);
    fiscalWeek = (diffWeeks % 52) + 1;
  } else {
    // Before 2026: 2025 had 53 weeks
    // diffWeeks=-1 → W53 2025, diffWeeks=-2 → W52 2025, etc.
    const backWeeks = -diffWeeks; // 1-based from end of 2025
    if (backWeeks <= 53) {
      fiscalYear = 2025;
      fiscalWeek = 54 - backWeeks;
    } else {
      // 2024: 52 weeks, anchor at W53 2025 → diffWeeks=-54 = W52 2024
      const backFrom2024 = backWeeks - 53;
      fiscalYear = 2024 - Math.floor((backFrom2024 - 1) / 52);
      fiscalWeek = 52 - ((backFrom2024 - 1) % 52);
    }
  }
  const wStart = thisSunday.toISOString().slice(0, 10);
  const wEndDate = new Date(thisSunday);
  wEndDate.setDate(thisSunday.getDate() + 6);
  const wEnd = wEndDate.toISOString().slice(0, 10);
  return { week: fiscalWeek, year: fiscalYear, weekStart: wStart, weekEnd: wEnd };
}

export function getWeek(dateStr) {
  return getFiscalWeekInfo(dateStr).week;
}

export function getFiscalMonthKey(dateStr) {
  // For straddling weeks: file under the month with more days
  if (!dateStr) return dateStr?.slice(0, 7) || '';
  const info = getFiscalWeekInfo(dateStr);
  // Count days of this week in each month
  const counts = {};
  for (let i = 0; i < 7; i++) {
    const d = new Date(info.weekStart + 'T00:00:00');
    d.setDate(d.getDate() + i);
    const mk = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    counts[mk] = (counts[mk] || 0) + 1;
  }
  // Return the month with the most days
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0];
}
export function calcServiceTotal(entry) {
  return SERVICE_FIELDS.filter(f => f.key !== 'myopia').reduce((s, f) => s + (parseFloat(entry[f.key]) || 0), 0);
}
